//! Sample game: one mesh per reference material from `quillshade/material/` and scene lighting from
//! `quillshade/light/`, generated by shader-editor.
//!
//! Everything comes from the generated baked API (design §3.1, §9.2): `BakedMaterialsLoader::load()` at startup, the
//! reserved handles of `BakedMaterials`, the images of `BakedTextures`, and `quillshade::light::Light` (`Preset::Day`
//! at startup; press `Space` to transition smoothly between `Preset::Day` and `Preset::Night` using `Curve::Smooth`).
//! Parameter values are the graph and environment defaults (compiled in, overlaid by
//! `assets/quillshade/{material,light}/autogen/baked.ron`); the game never constructs a material or manual light.
//!
//! Run with `cargo run` inside `examples/sample_game`; edit graphs, environments, curves, or Texture assets in the
//! editor while it runs — Bevy's file watcher hot-reloads the regenerated `.wesl` files and manifests.
//!
//! `SAMPLE_SCREENSHOT=out cargo run` saves `out-1.png` 5 s and `out-2.png` 25 s (wall clock, `Time<Real>`) after the
//! first frame, then exits once `out-2.png` is written. In this mode the window updates continuously even when it is
//! unfocused or hidden and does not wait for vsync, so the timers advance under software rendering too. Edit and
//! regenerate between the two shots to check hot reload.

use std::time::Duration;

use bevy::prelude::*;
use bevy::render::view::screenshot::{Screenshot, ScreenshotCaptured, save_to_disk};
use bevy::sprite_render::SpriteMaterial;
use bevy::window::PresentMode;
use bevy::winit::WinitSettings;
use quillshade::light::{Curve, Light, Preset, State};
use quillshade::material::{
    BakedMaterials, BakedMaterialsLoader, BakedMaterialsProgress, BakedMaterialsReady, BakedTextures,
};

/// `SAMPLE_SCREENSHOT` shots: (file suffix, seconds of real time after the first frame).
const SHOTS: [(u32, f64); 2] = [(1, 5.0), (2, 25.0)];

fn main() {
    let screenshot = std::env::var("SAMPLE_SCREENSHOT").ok();
    let present_mode = if screenshot.is_some() { PresentMode::AutoNoVsync } else { PresentMode::default() };
    let mut app = App::new();
    app.add_plugins(DefaultPlugins.set(WindowPlugin {
        primary_window: Some(Window { title: "shader-editor sample".into(), present_mode, ..default() }),
        ..default()
    }))
    .add_plugins(quillshade::QuillshadePlugin)
    .add_systems(Startup, (load_baked, setup).chain())
    .add_systems(Update, (rotate, toggle_light, log_loading, screenshot_and_exit))
    .add_systems(OnEnter(State::Day), || info!("lighting preset settled: Day"))
    .add_systems(OnEnter(State::Night), || info!("lighting preset settled: Night"));
    if let Some(prefix) = screenshot {
        app.insert_resource(WinitSettings::continuous()).insert_resource(ScreenshotRun {
            prefix,
            start: None,
            next: 0,
        });
    }
    app.run();
}

/// Starts loading the baked materials: `BakedMaterials` handles are usable right away, `BakedTextures` after this.
/// Optional — `QuillshadeMaterialInternalPlugin` starts loading in the first `PreUpdate` otherwise — but `setup` reads `BakedTextures`.
fn load_baked(mut loader: BakedMaterialsLoader) {
    info!("baked textures: loading {}", loader.load());
}

/// A loading screen would show this; materials render as soon as their images arrive either way.
fn log_loading(mut progress: MessageReader<BakedMaterialsProgress>, mut ready: MessageReader<BakedMaterialsReady>) {
    for p in progress.read() {
        info!("baked textures: {} loaded, {} failed of {}", p.loaded, p.failed, p.total);
    }
    if ready.read().count() > 0 {
        info!("baked materials ready");
    }
}

#[derive(Resource)]
struct ScreenshotRun {
    prefix: String,
    /// Real time of the first frame.
    start: Option<f64>,
    /// Index into `SHOTS` of the next screenshot.
    next: usize,
}

fn screenshot_and_exit(run: Option<ResMut<ScreenshotRun>>, time: Res<Time<Real>>, mut commands: Commands) {
    let Some(mut run) = run else { return };
    let now = time.elapsed_secs_f64();
    let start = *run.start.get_or_insert(now);
    let Some(&(i, at)) = SHOTS.get(run.next) else { return };
    if now - start < at {
        return;
    }
    run.next += 1;
    let mut shot = commands.spawn(Screenshot::primary_window());
    shot.observe(save_to_disk(format!("{}-{i}.png", run.prefix)));
    if run.next == SHOTS.len() {
        // `save_to_disk` writes synchronously in its observer; the app exits at the end of this frame.
        shot.observe(|_: On<ScreenshotCaptured>, mut exit: MessageWriter<AppExit>| {
            exit.write(AppExit::Success);
        });
    }
}

#[derive(Component)]
struct Spin;

fn setup(
    mut commands: Commands,
    mut meshes: ResMut<Assets<Mesh>>,
    baked: Res<BakedMaterials>,
    tex: Res<BakedTextures>,
    mut light: Light,
) {
    commands
        .spawn((Camera3d::default(), Transform::from_xyz(0.0, 3.0, 9.0).looking_at(Vec3::new(0.0, 0.5, 0.0), Vec3::Y)));
    commands.spawn((Camera2d, Camera { order: 1, clear_color: ClearColorConfig::None, ..default() }));
    light.set_immediate(Preset::Day);

    // Texture assets `textures/rock_albedo` (`.ktx2`) and `textures/rock_normal` (`.png`, `is_srgb: false`).
    let sphere = meshes.add(Sphere::new(1.0).mesh().uv(48, 24).with_generated_tangents().expect("tangents"));
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.rock_wet.clone()),
        Transform::from_xyz(-3.5, 1.0, 0.0),
        Spin,
    ));
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.exp42.clone()),
        Transform::from_xyz(0.0, 1.0, 0.0),
        Spin,
    ));
    // Grass on top, rock on the slopes: two `MaterialAttributes (PBR)` layers blended by `WorldAlignedBlend`.
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.terrain_layers.clone()),
        Transform::from_xyz(2.0, 0.8, 2.5).with_scale(Vec3::splat(0.8)),
    ));
    // Fixed textures inside functions (`common/tex_layer`, called directly and through `common/tex_layer_outer`).
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.tex_layers.clone()),
        Transform::from_xyz(-1.5, 0.45, 2.8).with_scale(Vec3::splat(0.45)),
        Spin,
    ));

    // `textures/water_normal`: `.ktx2`, `is_srgb: false`, repeating sampler.
    let plane =
        meshes.add(Plane3d::default().mesh().size(4.0, 4.0).build().with_generated_tangents().expect("tangents"));
    commands.spawn((Mesh3d(plane), MeshMaterial3d(baked.env.water.clone()), Transform::from_xyz(0.0, 0.0, 0.0)));

    let cloth = meshes.add(Plane3d::new(Vec3::Z, Vec2::new(1.0, 0.6)).mesh().subdivisions(24).build());
    commands.spawn((Mesh3d(cloth), MeshMaterial3d(baked.env.flag.clone()), Transform::from_xyz(3.0, 1.5, 0.0)));

    commands.spawn((
        Mesh3d(meshes.add(Cylinder::new(0.6, 1.6))),
        MeshMaterial3d(baked.fx.hologram.clone()),
        Transform::from_xyz(0.0, 1.2, -2.0),
    ));

    // `textures/atlas` with a Nearest sampler (switch it to Linear in the editor to see the sampler hot-reload).
    commands.spawn((
        Mesh3d(meshes.add(Cuboid::new(1.0, 1.0, 1.0))),
        MeshMaterial3d(baked.fx.coords.clone()),
        Transform::from_xyz(0.0, 2.8, 0.0),
        Spin,
    ));

    // Bands shaped by the curve assets `common/pulse` and `common/steps`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(baked.fx.curve_bands.clone()),
        Transform::from_xyz(3.3, 3.3, 0.0),
    ));

    // Colors, stripes and the striped branch come from the global constants of `common/tuning`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(baked.fx.global_tint.clone()),
        Transform::from_xyz(-3.3, 3.3, 0.0),
    ));

    // The sprite image comes from `BakedTextures` (filled by `load()`), so its Texture asset settings apply; a plain
    // `assets.load` of the same file could win Bevy's "first load wins" and drop them.
    commands.spawn((
        Sprite::from_image(tex.textures.sprite.clone()),
        SpriteMaterial(baked.ui.dissolve.clone()),
        Transform::from_xyz(-500.0, 250.0, 0.0).with_scale(Vec3::splat(2.0)),
    ));
}

fn rotate(time: Res<Time>, mut q: Query<&mut Transform, With<Spin>>) {
    for mut t in &mut q {
        t.rotate_y(time.delta_secs() * 0.4);
    }
}

fn toggle_light(keys: Res<ButtonInput<KeyCode>>, mut light: Light) {
    if keys.just_pressed(KeyCode::Space) {
        let next = match light.next_preset().or(light.current_preset()) {
            Some(Preset::Day) => Preset::Night,
            _ => Preset::Day,
        };
        light.transition_to(next, Curve::Smooth, Duration::from_secs(3));
    }
}
